package main

import (
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
	"io"
	"log"
)

// Reading is one packet from a (made-up) greenhouse sensor: 12 bytes, big-endian.
type Reading struct {
	Magic    [2]byte // "SL"
	Version  uint8
	Flags    uint8
	DeviceID uint32
	TempDeci int16  // tenths of a degree: -125 is -12.5 °C
	Humidity uint16 // tenths of a percent
}

func main() {
	pkt := []byte{'S', 'L', 1, 0, 0x00, 0x01, 0xE2, 0x40, 0xFF, 0x83, 0x02, 0x6C}

	// Field by field: explicit offsets, no reflection.
	fmt.Println("device id, big-endian:   ", binary.BigEndian.Uint32(pkt[4:8]))
	fmt.Println("device id, little-endian:", binary.LittleEndian.Uint32(pkt[4:8]))

	// The whole struct: fields are read in order, packed, with no padding.
	var r Reading
	if err := binary.Read(bytes.NewReader(pkt), binary.BigEndian, &r); err != nil {
		log.Fatal(err)
	}
	fmt.Printf("%+v\n", r)
	fmt.Printf("%.1f °C, %.1f %% humidity, %d bytes on the wire\n",
		float64(r.TempDeci)/10, float64(r.Humidity)/10, binary.Size(r))

	// Encoding: Append (Go 1.23) builds the bytes without an io.Writer.
	r.TempDeci = 215
	out, err := binary.Append(nil, binary.BigEndian, r)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Printf("% x\n", out)

	// A short packet is an error, not a half-filled struct.
	err = binary.Read(bytes.NewReader(pkt[:7]), binary.BigEndian, &r)
	fmt.Println("7 of 12 bytes:", err, errors.Is(err, io.ErrUnexpectedEOF))

	// Varints: small numbers take fewer bytes (protobuf uses the same scheme).
	for _, n := range []uint64{5, 300, 1 << 32} {
		fmt.Printf("uvarint %d -> % x\n", n, binary.AppendUvarint(nil, n))
	}
}

files.examples/02_gzip.go:
package main

import (
	"bufio"
	"bytes"
	"compress/gzip"
	"errors"
	"fmt"
	"io"
	"log"
	"os"
)

func writeGzip(name string, rows int) (err error) {
	f, err := os.Create(name)
	if err != nil {
		return err
	}
	defer func() { err = errors.Join(err, f.Close()) }()

	zw := gzip.NewWriter(f) // an io.Writer that compresses into another io.Writer
	zw.Name = "siparisler.csv"
	for i := range rows {
		fmt.Fprintf(zw, "%d;İstanbul;%d\n", i, i*7)
	}
	return zw.Close() // writes the footer (CRC-32 and size); f.Close doesn't
}

func main() {
	if err := writeGzip("siparisler.csv.gz", 10000); err != nil {
		log.Fatal(err)
	}
	f, err := os.Open("siparisler.csv.gz")
	if err != nil {
		log.Fatal(err)
	}
	defer f.Close()
	zr, err := gzip.NewReader(f) // an io.Reader that decompresses
	if err != nil {
		log.Fatal(err)
	}
	sc := bufio.NewScanner(zr)
	lines, last := 0, ""
	for sc.Scan() {
		lines, last = lines+1, sc.Text()
	}
	if err := sc.Err(); err != nil { // a corrupt or truncated file shows up here
		log.Fatal(err)
	}
	fmt.Println(zr.Name, "lines:", lines, "last:", last)

	bad := gzip.NewWriter(io.Discard)
	bad.Name = "Şubat.csv" // header strings are Latin-1 only; Ş is U+015E
	_, err = bad.Write([]byte("x"))
	fmt.Println(err)

	var buf bytes.Buffer
	zw := gzip.NewWriter(&buf)
	zw.Write([]byte("ay;tutar\nKasım;100\n"))
	zw.Flush() // Flush without Close: the data is there, the footer is not
	zr2, _ := gzip.NewReader(&buf)
	data, err := io.ReadAll(zr2)
	fmt.Printf("%q, %v\n", data, err)
}

files.examples/03_zip.go:
package main

import (
	"archive/zip"
	"fmt"
	"io/fs"
	"log"
	"os"
	"path/filepath"
)

func main() {
	f, err := os.Create("rapor.zip")
	if err != nil {
		log.Fatal(err)
	}
	zw := zip.NewWriter(f)
	for _, name := range []string{"raporlar/Ocak.csv", "raporlar/Şubat.csv", "../../evil.txt"} {
		w, err := zw.Create(name) // Deflate; the writer doesn't validate the name
		if err != nil {
			log.Fatal(err)
		}
		fmt.Fprintf(w, "ay;tutar\n%s;100\n", filepath.Base(name))
	}
	if err := zw.Close(); err != nil { // writes the central directory: no Close, no archive
		log.Fatal(err)
	}
	if err := f.Close(); err != nil {
		log.Fatal(err)
	}

	zr, err := zip.OpenReader("rapor.zip")
	if err != nil {
		log.Fatal(err)
	}
	defer zr.Close()
	for _, zf := range zr.File { // raw entries: names exactly as stored
		fmt.Printf("%-20q utf8-flag=%-5t IsLocal=%t\n",
			zf.Name, zf.Flags&0x800 != 0, filepath.IsLocal(zf.Name))
	}

	// The fs.FS view cleans names: no "..", no leading "/". CopyFS (Go 1.23)
	// extracts through it, so nothing lands outside "out".
	if err := os.CopyFS("out", zr); err != nil {
		log.Fatal(err)
	}
	err = fs.WalkDir(os.DirFS("out"), ".", func(name string, d fs.DirEntry, err error) error {
		if err == nil && !d.IsDir() {
			fmt.Println("extracted:", name)
		}
		return err
	})
	if err != nil {
		log.Fatal(err)
	}
}
